{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Propafenone had a mean absolute oral bioavailability of 13% at a 150 mg therapeutic dose in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "DX-9065a had a human absolute oral bioavailability of 2–3%, affirmatively below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Aspirin had an absolute oral bioavailability of 56.5 ± 5.6% in patients, above the 20% threshold and therefore contradictory to a low prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer evidence molecules are predominantly low: propafenone (13%), DX-9065a (2–3%), acamprosate (11%), selegiline and phenylephrine (low), and compound 26 (predicted 0%). The main contradictory high-bioavailability record is aspirin (~56%) with a lower assay-transfer score; lercanidipine is mixed and naltrexone is uninformative. Thus low is better supported.",
  "evidence_gaps": [
    "Molecule 5 (lercanidipine) has conflicting absolute bioavailability reports (about 10% in fed patients vs about 30% in an unspecified condition), so its direction is uncertain.",
    "Molecule 6 (naltrexone) reports only a broad range (5–40%) spanning the threshold, so it is uninformative for the F≥20% classification.",
    "Molecule 10's 0% oral bioavailability is a prediction from animal data rather than a measured human value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

